/*!50003 CREATE*/ /*!50017 DEFINER=`sa`@`%`*/ /*!50003 TRIGGER utrigger_Rera_RenewalAgent_ChecklistRecord_INSERT
AFTER INSERT ON
tbl_rera_authdesk_agent_renewal_checklistaction
FOR EACH ROW
BEGIN      
     Declare v_AgentID BigInt; 
     Declare v_AgentType int;
     Declare v_RnAgentID BigInt;
     Declare v_RnAgentSequenceID int;
     Declare v_RnAgentYear int;
     Declare v_RnAgentDiaryNumber varchar(100); 
     Declare v_RefRegistrationNumber varchar(100);
     Declare v_CriteriaCode int;
     Declare v_SubCriteriaCode int;
     Declare v_ChecklistStatus varchar(10);
     
    SET v_AgentID=NEW.Related_Agent_ID;         
    SET v_AgentType=NEW.Related_AgentType_ID;
    SET v_RnAgentID=NEW.Related_RenewalAgent_ID;
    SET v_RnAgentSequenceID=NEW.Related_RenewalAgent_SequenceID;
    SET v_RnAgentYear=NEW.Related_RenewalAgent_Year;    
    SET v_RnAgentDiaryNumber=NEW.RelatedAgent_RenewalDiaryNumber;
    SET v_RefRegistrationNumber=NEW.RERAnumberRegistration;
    SET v_CriteriaCode=NEW.CriteriaCode;
    SET v_SubCriteriaCode=NEW.CriteriaSubCode;
    SET v_ChecklistStatus=NEW.IsChecklistValueOk;
 
-- Renewal of Registration (Agent) Details

-- Profile (Ind/OTI/Authorized Person) Details          
If (v_SubCriteriaCode = 3216 or v_SubCriteriaCode = 3220 or v_SubCriteriaCode = 3221)
then 
   If (v_ChecklistStatus = 'N')
   then
 		update tbl_rera_agent_renewal_profile set IsDraft=5	
 		where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and RenewalAgent_ID=v_RnAgentID
        and RenewalOrderSequence=v_RnAgentSequenceID
        and RelatedRenewalAgent_Year=v_RnAgentYear
 		and IsActive=1 and IsDraft=1;
   else
 		update tbl_rera_agent_renewal_profile set IsDraft=1	
 		where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and RenewalAgent_ID=v_RnAgentID
        and RenewalOrderSequence=v_RnAgentSequenceID
        and RelatedRenewalAgent_Year=v_RnAgentYear  
 		and IsActive=1 and IsDraft=5;
   end if;
end if;

-- Other Organization Members 
If (v_SubCriteriaCode = 3203)
then 
  If (v_ChecklistStatus = 'N')
  then
 	   update tbl_rera_agent_renewal_othermemberdetail set IsDraft=5	
 	   where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and Related_RenewalAgent_ID=v_RnAgentID
        and Related_RenewalOrderSequence=v_RnAgentSequenceID
        and Related_RelatedRenewalAgent_Year=v_RnAgentYear  
 	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_renewal_othermemberdetail set IsDraft=1	
 	   where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and Related_RenewalAgent_ID=v_RnAgentID
        and Related_RenewalOrderSequence=v_RnAgentSequenceID
        and Related_RelatedRenewalAgent_Year=v_RnAgentYear  
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;     

-- Renewal-Agent Payment or Fee Details          
If (v_SubCriteriaCode = 3213)
then 
  If (v_ChecklistStatus = 'N')
  then
	   update tbl_rera_agent_renewal_payment set IsDraft=5	
	   where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and Related_RenewalAgent_ID=v_RnAgentID
        and Related_RenewalOrderSequence=v_RnAgentSequenceID
        and Related_RelatedRenewalAgent_Year=v_RnAgentYear  
	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_renewal_payment set IsDraft=1	
  	   where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and Related_RenewalAgent_ID=v_RnAgentID
        and Related_RenewalOrderSequence=v_RnAgentSequenceID
        and Related_RelatedRenewalAgent_Year=v_RnAgentYear 
  	   and IsActive=1 and IsDraft=5;
  end if;
end if;

-- Other State-UT RERA Details          
If (v_SubCriteriaCode = 3215)
then 
  If (v_ChecklistStatus = 'N')
  then
	   update tbl_rera_agent_renewal_otherstateut_regreradetails set IsDraft=5	
 	   where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and Related_RenewalAgent_ID=v_RnAgentID
        and Related_RenewalOrderSequence=v_RnAgentSequenceID
        and Related_RelatedRenewalAgent_Year=v_RnAgentYear  
 	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_renewal_otherstateut_regreradetails set IsDraft=1	
  	   where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and Related_RenewalAgent_ID=v_RnAgentID
        and Related_RenewalOrderSequence=v_RnAgentSequenceID
        and Related_RelatedRenewalAgent_Year=v_RnAgentYear  
  	   and IsActive=1 and IsDraft=5;
  end if;
end if;


-- -- ## Document (Renewal-Agent) Details ## --
-- Documents (Place of Bussiness Address Proof)         
If (v_SubCriteriaCode = 3206 or v_SubCriteriaCode = 3207)
then 
  If (v_ChecklistStatus = 'N')
  then
 	   update tbl_rera_agent_renewal_documents set IsDraft=5	
 	   where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and Related_RenewalAgent_ID=v_RnAgentID
        and Related_RenewalOrderSequence=v_RnAgentSequenceID
        and Related_RelatedRenewalAgent_Year=v_RnAgentYear
       and AgentDoc_InfoCode=402        
 	   and IsActive=1 and IsDraft=1;
  else
       update tbl_rera_agent_renewal_documents set IsDraft=1	
 	   where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and Related_RenewalAgent_ID=v_RnAgentID
        and Related_RenewalOrderSequence=v_RnAgentSequenceID
        and Related_RelatedRenewalAgent_Year=v_RnAgentYear
       and AgentDoc_InfoCode=402
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;

-- Documents (Pan Copy (Individual or Organization))         
If (v_SubCriteriaCode = 3208)
then 
  If (v_ChecklistStatus = 'N')
