  else
       update tbl_rera_agent_renewal_documents set IsDraft=1	
  	   where Related_Agent_ID=v_AgentID
        and Related_Agent_Type=v_AgentType
        and Related_RenewalAgent_ID=v_RnAgentID
        and Related_RenewalOrderSequence=v_RnAgentSequenceID
        and Related_RelatedRenewalAgent_Year=v_RnAgentYear
       and AgentDoc_InfoCode in (404,411,412)
 	   and IsActive=1 and IsDraft=5;
  end if;
end if;

-- Documents (Company Registration Certificate or Registration By-Law or MOA or AOA)         
If (v_SubCriteriaCode = 3214)
